
(async function() {
  const token = localStorage.getItem("token");
  const gameId = "79651";
  const md5 = "0677eebb63a2464b8aa08bd6f9d08a81";
  const assets = [{"name":"512x384.jpg","width":512,"height":384,"base64":""},{"name":"512x512.jpg","width":512,"height":512,"base64":""},{"name":"200x120.jpg","width":200,"height":120,"base64":""},{"name":"1280x720.jpg","width":1280,"height":720,"base64":""},{"name":"1280x550.jpg","width":1280,"height":550,"base64":""}];
  window.__uploadResults = [];

  for (const asset of assets) {
    const byteCharacters = atob(asset.base64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: "image/jpeg" });
    const file = new File([blob], asset.name, { type: "image/jpeg" });

    const formData = new FormData();
    formData.append("file", file);
    formData.append("width", asset.width.toString());
    formData.append("height", asset.height.toString());
    formData.append("gameId", gameId);
    formData.append("name", asset.name);

    try {
      const res = await fetch("https://developer-api-nest-prod-aws.gamedistribution.com/api/v1.0/assets/storage/" + md5, {
        method: "POST",
        headers: {
          "Authorization": "Bearer " + token,
          "X-Requested-With": "XMLHttpRequest"
        },
        body: formData
      });
      const data = await res.json();
      window.__uploadResults.push({ name: asset.name, status: res.status, ok: res.ok, result: data });
    } catch(e) {
      window.__uploadResults.push({ name: asset.name, error: e.message });
    }
  }
  window.__uploadDone = true;
})();
